    def is_first_digit_odd(x):
        while x >= 10:
            x //= 10
        return x % 2 == 1

    def is_last_digit_odd(x):
        return (x % 10) % 2 == 1

    count = 0
    for num in nums:
        if num > 10 and is_first_digit_odd(num) and is_last_digit_odd(num):
            count += 1
    return count

